function hydrateDeal(p: CompactDeal, idx: number): BookingDealItem {
  const brandName = p.brandName || 'Kutieskin';
  const bookingBatch = p.bookingBatch ?? '2026/09';
  const totalValue = p.totalValue ?? 0;
  const advanceAmount = p.advanceAmount ?? 0;
  const gmv30 = p.gmv30 ?? 0;
  const performanceRating = p.performanceRating ?? 'CẦN_CẢI_THIỆN';
  const videoUrl = p.videoUrl;
  const assignedStaff = p.assignedStaff;
  const deadlinePost = p.deadlinePost;
  return {
    id: p.id || `deal-real-${idx + 1}`,
    dealCode: p.dealCode,
    jobId: p.dealCode.replace(/^BO/, 'ID'),
    campaignCode: `CAMP-${(brandName || 'B2C').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 6)}-${((bookingBatch || '2026').replace(/\D/g, '').slice(-4) || '2026')}`,
    campaignTitle: `Chiến dịch Booking ${brandName || 'B2C'} (${bookingBatch || '2026'})`,
    brandName,
    storeName: p.storeName,
    productName: p.productName,
    bookingBatch,
    bookingFormat: p.bookingFormat ?? 'Booking Video KOC',
    kocId: p.kocId,
    kocStageName: p.kocStageName,
    kocChannelId: p.kocChannelId,
    kocTier: p.kocTier ?? 'TIER_4_AFFILIATE',
    salaryGrade: p.salaryGrade ?? 'TAP UpAffiliate',
    segment: p.segment ?? 'Massive Creator',
    tepKenh: p.tepKenh ?? 'Review Nữ',
    kocCategory: p.kocCategory ?? 'Reviewer',
    contentPillar: p.contentPillar ?? 'Review trực tiếp',
    brandApprovalStatus: 'ĐÃ_DUYỆT',
    kocResponseStatus: 'ĐỒNG_Ý',
    pipelineText: p.pipelineText ?? 'Gửi hàng',
    status: p.status ?? 'SAMPLE_SHIPPED',
    statusLabel: p.statusLabel ?? 'Đang Gửi Mẫu Sản Phẩm',
    sampleStatus: 'ĐÃ_NHẬN',
    adsCodeStatus: p.sparkAdsCode ? 'ĐÃ_NGHIỆM_THU' : 'CHƯA_CẤP',
    ...(p.sparkAdsCode !== undefined ? { sparkAdsCode: p.sparkAdsCode } : {}),
    ...(videoUrl !== undefined ? { videoUrl, tiktokVideoUrl: videoUrl } : {}),
    assignedStaff,
    bookingPic: assignedStaff,
    ...(p.accountPic !== undefined ? { accountPic: p.accountPic } : {}),
    ...(p.leadBooking !== undefined ? { leadBooking: p.leadBooking } : {}),
    ...(p.contentNote !== undefined ? { contentNote: p.contentNote } : {}),
    totalValue,
    advanceAmount,
    finalAmount: Math.max(0, totalValue - advanceAmount),
    deadlinePost,
    postedDate: deadlinePost,
    viewsCount: p.viewsCount ?? 0,
    affiliateGmv: gmv30,
    gmv30,
    roi: p.roi ?? 0,
    publishedDays: 30,
    isWinnerTop20: p.isWinnerTop20 ?? false,
    hasGmv: gmv30 > 0,
    isBreakEven: p.isBreakEven ?? false,
    remainingSlaHours: 0,
    isSlaWarning: false,
    ordersCount: p.ordersCount ?? 0,
    ...(p.cpo !== undefined ? { cpo: p.cpo } : {}),
    ...(p.isScriptOnTime !== undefined ? { isScriptOnTime: p.isScriptOnTime } : {}),
    ...(p.isPostOnTime !== undefined ? { isPostOnTime: p.isPostOnTime } : {}),
    ratingScore: performanceRating === 'XUẤT_SẮC' ? 4.9 : performanceRating === 'ĐẠT_MỤC_TIÊU' ? 4.5 : 4.0,
    performanceRating,
    ...(p.signedContractUrl !== undefined ? { signedContractUrl: p.signedContractUrl } : {}),
  };
}

export const REAL_KOC_COOPERATION_DEALS: BookingDealItem[] = RAW_COMPACT_DEALS.map(hydrateDeal);
